// Übersetzt ContentForge-Events in eine Adaptive Card für Microsoft Teams (Human in the Loop).
const EVENTS = {
  'run.awaiting_approval': { title: 'Neuer Content wartet auf Freigabe', color: 'Accent' },
  'run.needs_review': { title: 'Quality Gate nicht bestanden – bitte manuell prüfen', color: 'Warning' },
  'run.failed': { title: 'Pipeline fehlgeschlagen', color: 'Attention' },
  'run.published': { title: 'Landingpage veröffentlicht', color: 'Good' },
};

const out = [];
for (const item of $input.all()) {
  const e = item.json.body ?? item.json;
  const cfg = EVENTS[e.event];
  if (!cfg) continue; // z. B. run.rejected: keine Benachrichtigung nötig

  const facts = [
    { title: 'Keyword', value: e.keyword },
    { title: 'Revisionen', value: String(e.revisions ?? 0) },
    { title: 'Judge-Score', value: e.judge_average != null ? `${e.judge_average} / 5` : '–' },
    { title: 'Kosten', value: `$${Number(e.cost_usd ?? 0).toFixed(3)}` },
  ];
  if (e.error) facts.push({ title: 'Fehler', value: e.error });

  const actions = e.event === 'run.published'
    ? [{ type: 'Action.OpenUrl', title: 'Seite öffnen', url: e.published_url }]
    : [
        { type: 'Action.OpenUrl', title: 'Prüfen & freigeben', url: e.dashboard_url },
        { type: 'Action.OpenUrl', title: 'Vorschau', url: e.preview_url },
      ];

  out.push({
    json: {
      event: e.event,
      run_id: e.run_id,
      teamsConfigured: Boolean($env.TEAMS_WEBHOOK_URL),
      teams: {
        type: 'message',
        attachments: [{
          contentType: 'application/vnd.microsoft.card.adaptive',
          content: {
            $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
            type: 'AdaptiveCard',
            version: '1.4',
            body: [
              { type: 'TextBlock', text: cfg.title, weight: 'Bolder', size: 'Medium', color: cfg.color, wrap: true },
              { type: 'FactSet', facts },
            ],
            actions,
          },
        }],
      },
    },
  });
}
return out;
